#include <stdio.h>   /* a preprocessor directive: no semicolon */

// A single-line comment runs to the end of the line.

int main(void)
{
    int width = 4;      /* declaration with an initialiser */
    int height = 3;
    int area;           /* declaration without a value yet */

    area = width * height;       /* assignment statement */
    printf("Area: %d\n", area);  /* function-call statement */

    /* A block groups statements; this one belongs to the if. */
    if (area > 10) {
        printf("That is a big rectangle.\n");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int count = 10;             /* whole number */
    double temperature = 21.5;  /* number with a fractional part */
    char grade = 'B';           /* one character, in single quotes */
    int x = 1, y = 2, z;        /* several at once; z has no value yet */

    z = x + y;
    count = count + 5;          /* reassignment replaces the old value */
    temperature = temperature - 0.5;

    printf("count = %d\n", count);
    printf("temperature = %.1f\n", temperature);
    printf("grade = %c\n", grade);
    printf("z = %d\n", z);
    return 0;
}

