    printf("%d\n", total);
    return 0;
}

#include <stdio.h>

#define TAX_RATE 0.2        /* macro: text replaced before compiling */
enum { MAX_ITEMS = 3 };     /* enumeration constant: a real integer constant */

int main(void)
{
    const double base_price = 50.0;   /* read-only variable */
    int prices[MAX_ITEMS] = {10, 20, 30};

    printf("With tax: %.2f\n", base_price * (1 + TAX_RATE));
    printf("Items: %d, last price: %d\n", MAX_ITEMS, prices[MAX_ITEMS - 1]);
    /* base_price = 60.0;  does not compile: assignment of read-only variable */
    return 0;
}

#include <stdio.h>

int calls = 0;          /* file scope: visible to every function below */

int main(void)
{
    int value = 1;      /* block scope: the body of main */
    calls++;

    {
        int value = 2;  /* a new variable that shadows the outer one */
        printf("inner value = %d\n", value);
    }

    for (int i = 0; i < 2; i++) {   /* i exists only inside the loop */
        calls++;
    }

    printf("outer value = %d\n", value);
    printf("calls = %d\n", calls);
    return 0;
}
